// FlexSearch engine for the shared search panel (panel.js).
// Index: per-language searchindex.json generated by
// layouts/home.searchindex.json; the URL comes from
// #search-panel[data-index-url] so this script stays language-independent.
// Originally based on https://github.com/frjo/hugo-theme-zen/blob/main/assets/js/search.js
import { initPanel, escapeHtml, termRanges } from "./panel.js";
import { initSearchHighlight } from "./highlight.js";

(function () {
  "use strict";

  const panel = document.getElementById("search-panel");
  if (!panel) return;

  const searchLimit = parseInt(panel.dataset.searchLimit, 10) || 20;

  // Han/Kana lack spaces: without per-char isolation FlexSearch indexes a
  // whole punctuation-free run as one token, so only run-prefix queries
  // match. Composing with the default encoder keeps its Latin folding
  // (diacritics, full-width forms).
  const unspaced = /\p{Script=Han}|\p{Script=Hiragana}|\p{Script=Katakana}/gu;
  const encoder = new FlexSearch.Encoder();
  const index = new FlexSearch.Document({
    document: {
      id: "id",
      index: ["title", "tags", "content", "date"],
      store: ["title", "summary", "date", "permalink"],
    },
    tokenize: "forward",
    encode: (str) => encoder.encode(str.replace(unspaced, " $& ")),
  });

  let ready = false;

  fetch(panel.dataset.indexUrl)
    .then(function (response) {
      return response.json();
    })
    .then(function (data) {
      data.forEach(function (item) {
        index.add(item);
      });
      ready = true;
      ui.refresh();
    })
    .catch(function () {
      // Leave the panel usable (empty state) instead of stuck on loading.
      ready = true;
      ui.refresh();
    });

  // Wrap query-term occurrences in <mark>. Segments are escaped individually
  // before injection, so the markup is safe even for hostile index text.
  function highlight(text, terms) {
    if (!terms.length) return escapeHtml(text);
    const lower = text.toLowerCase();
    let out = "";
    let cursor = 0;
    termRanges(lower, terms).forEach(function (m) {
      out += escapeHtml(text.slice(cursor, m[0]));
      out += "<mark>" + escapeHtml(text.slice(m[0], m[1])) + "</mark>";
      cursor = m[1];
    });
    return out + escapeHtml(text.slice(cursor));
  }

  const ui = initPanel({
    ready: function () {
      return ready;
    },
    search: function (q) {
      if (!ready) return undefined;
      const results = index.search({
        query: q,
        enrich: true,
        limit: searchLimit,
      });
      const items = {};
      results.forEach(function (result) {
        result.result.forEach(function (r) {
          items[r.doc.permalink] = r.doc;
        });
      });
      const terms = q.toLowerCase().split(/\s+/).filter(Boolean);
      return Object.values(items).map(function (doc) {
        return {
          url: doc.permalink,
          titleHtml: highlight(doc.title, terms),
          summaryHtml: highlight(doc.summary, terms),
          dateText: doc.date,
        };
      });
    },
  });

  initSearchHighlight(document.getElementById("main-content"));
})();
